secret = 42
attempts = 0
while True:
    guess = int(input())
    attempts += 1
    if guess < secret:
        print("Too low")
    elif guess > secret:
        print("Too high")
    else:
        print(f"Correct! Attempts: {attempts}")
        break

tasks = []
while True:
    line = input()
    if line == "quit":
        break
    if line.startswith("add "):
        tasks.append([line[4:], False])
    elif line.startswith("done "):
        tasks[int(line[5:]) - 1][1] = True
    elif line == "list":
        if not tasks:
            print("Empty")
        for i, (text, done) in enumerate(tasks, start=1):
            print(f"{i}. [{'x' if done else ' '}] {text}")

class BankAccount:
    def __init__(self):
        self.balance = 0

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            print("Insufficient funds")
        else:
            self.balance -= amount

account = BankAccount()
while True:
    cmd = input().split()
    if cmd[0] == "quit":
        break
    if cmd[0] == "deposit":
        account.deposit(int(cmd[1]))
    elif cmd[0] == "withdraw":
        account.withdraw(int(cmd[1]))
    elif cmd[0] == "balance":
        print(f"Balance: {account.balance}")
